1	import { Block, Text } from "@prototyp/skeletor";
2	import { FlashList, type FlashListRef } from "@shopify/flash-list";
3	import type { RoomInterface } from "@unomed/react-native-matrix-sdk";
4	import { TimelineItemContent_Tags } from "@unomed/react-native-matrix-sdk";
5	import { useAtom } from "jotai";
6	import {
7	  addDateDividers,
8	  getEventId,
9	  getItemUniqueKey,
10	  groupInfoEvents,
11	} from "modules/matrix-client/utils";
12	import { useRoomIdentityViolations } from "modules/room/hooks";
13	import { useRoomTimeline } from "modules/timeline/hooks";
14	import { TimelineAtoms } from "modules/timeline/jotai";
15	import { filterSameStateKey } from "modules/timeline/utils";
16	import {
17	  type FC,
18	  useCallback,
19	  useEffect,
20	  useMemo,
21	  useRef,
22	  useState,
23	} from "react";
24	import {
25	  Image,
26	  KeyboardAvoidingView,
27	  type NativeScrollEvent,
28	  type NativeSyntheticEvent,
29	  StyleSheet,
30	} from "react-native";
31	import {
32	  Button,
33	  MemberDetailsBottomSheet,
34	  SeenByBottomSheet,
35	} from "shared/components";
36	import { useMemberDetails } from "shared/hooks";
37	import { DateDivider } from "../date-divider";
38	import { GroupedInfoMessages } from "../grouped-info-messages";
39	import { MessageContentBottomSheet } from "../message-content-bottom-sheet";
40	import { RoomIdentityBanner } from "../room-identity-banner";
41	import { RoomInput } from "../room-input";
42	import { SingleMessageType } from "../single-message-type";
43	
44	interface Props {
45	  room: RoomInterface;
46	  roomId: string;
47	}
48	
49	export const RoomTimeline: FC<Props> = ({ room, roomId }) => {
50	  const flashListRef = useRef<FlashListRef<TimelineListItem>>(null);
51	  const isAtBottomRef = useRef(true);
52	  const lastEventKeyRef = useRef<string | undefined>(undefined);
53	  const lastBottomEventKeyRef = useRef<string | undefined>(undefined);
54	  const scrollTimeoutRef = useRef<ReturnType<typeof setTimeout>>(undefined);
55	  const [showScrollDown, setShowScrollDown] = useState(false);
56	  const {
57	    events,
58	    refreshing,
59	    isPaginatingRef,
60	    isDirect,
61	    loadMoreMessages,
62	    markAsRead,
63	  } = useRoomTimeline({
64	    room,
65	    roomId,
66	  });
67	  const [scrollToEventId, setScrollToEventId] = useAtom(
68	    TimelineAtoms.scrollToEventId,
69	  );
70	  const [seenByUserIds, setSeenByUserIds] = useAtom(
71	    TimelineAtoms.seenByUserIds,
72	  );
73	  const { isPinViolatingUsersLoading, violatingUsers, pinViolatingUsers } =
74	    useRoomIdentityViolations(room);
75	  const {
76	    selectedMember,
77	    isBottomSheetOpen,
78	    openMemberDetails,
79	    closeMemberDetails,
80	  } = useMemberDetails();
81	
82	  const sortedEvents = useMemo(() => {
83	    const sorted = [...events].sort(
84	      (a, b) => Number(a.timestamp) - Number(b.timestamp),
85	    );
86	
87	    return filterSameStateKey(sorted);
88	  }, [events]);
89	
90	  const eventsWithDividers = useMemo(() => {
91	    const items = groupInfoEvents(addDateDividers(sortedEvents));
92	
93	    // Pre-compute isPreviousSameSender so it's not recalculated per-item during render
94	    let prevSender: string | null = null;
95	    for (const item of items) {
96	      if (item.type !== "event") {
97	        prevSender = null;
98	        continue;
99	      }
100	      const isMsgLike =
101	        item.data.content.tag === TimelineItemContent_Tags.MsgLike;
102	      if (!isMsgLike) {
103	        prevSender = null;
104	        continue;
105	      }
106	      item.isPreviousSameSender =
107	        isDirect || (prevSender !== null && prevSender === item.data.sender);
108	      prevSender = item.data.sender;
109	    }
110	
111	    return items;
112	  }, [sortedEvents, isDirect]);
113	
114	  const handleScrollToEvent = useCallback(
115	    (eventId: string) => {
116	      const index = eventsWithDividers.findIndex(
117	        (item) => item.type === "event" && getEventId(item.data) === eventId,
118	      );
119	      if (index === -1) return;
120	
121	      flashListRef.current?.scrollToIndex({
122	        index,
123	        animated: true,
124	        viewPosition: 0.5,
125	      });
126	    },
127	    [eventsWithDividers],
128	  );
129	
130	  useEffect(() => {
131	    if (!scrollToEventId) return;
132	    handleScrollToEvent(scrollToEventId);
133	    setScrollToEventId(null);
134	  }, [scrollToEventId, handleScrollToEvent, setScrollToEventId]);
135	
136	  const handleLoadMore = async () => {
137	    setShowScrollDown(false);
138	    await loadMoreMessages();
139	  };
140	
141	  const handleScrollDown = () => {
142	    flashListRef.current?.scrollToEnd({ animated: true });
143	    setShowScrollDown(false);
144	  };
145	
146	  const handleOnScroll = ({
147	    nativeEvent,
148	  }: NativeSyntheticEvent<NativeScrollEvent>) => {
149	    const { layoutMeasurement, contentOffset, contentSize } = nativeEvent;
150	    const paddingToBottom = 100;
151	    const atBottom =
152	      layoutMeasurement.height + contentOffset.y >=
153	      contentSize.height - paddingToBottom;
154	    isAtBottomRef.current = atBottom;
155	    if (!atBottom) return;
156	    setShowScrollDown(false);
157	    markAsRead();
158	  };
159	
160	  const handleContentSizeChange = () => {
161	    if (isPaginatingRef.current) return;
162	
163	    const lastEvent = sortedEvents[sortedEvents.length - 1];
164	    const lastEventKey = lastEvent
165	      ? (getItemUniqueKey(lastEvent) ?? undefined)
166	      : undefined;
167	    const isNewEvent = lastEventKey !== lastEventKeyRef.current;
168	    lastEventKeyRef.current = lastEventKey;
169	    const shouldScrollToEnd =
170	      (isNewEvent && !!lastEvent?.isOwn) || isAtBottomRef.current;
171	    if (!shouldScrollToEnd) return;
172	    if (scrollTimeoutRef.current) clearTimeout(scrollTimeoutRef.current);
173	    scrollTimeoutRef.current = setTimeout(() => {
174	      flashListRef.current?.scrollToEnd({ animated: true });
175	    }, 100);
176	  };
177	
178	  useEffect(() => {
179	    const lastEvent = sortedEvents[sortedEvents.length - 1];
180	    const lastEventKey = lastEvent
181	      ? (getItemUniqueKey(lastEvent) ?? undefined)
182	      : undefined;
183	    const isNewMessageAtBottom = lastEventKey !== lastBottomEventKeyRef.current;
184	    lastBottomEventKeyRef.current = lastEventKey;
185	    if (!isNewMessageAtBottom || isAtBottomRef.current || lastEvent?.isOwn) {
186	      return;
187	    }
188	    setShowScrollDown(true);
189	  }, [sortedEvents]);
190	
191	  const renderItem = useCallback(
192	    ({ item }: { item: TimelineListItem }) => {
193	      if (item.type === "divider") {
194	        return <DateDivider date={item.date} />;
195	      }
196	
197	      if (item.type === "group") {
198	        return <GroupedInfoMessages events={item.events} roomId={roomId} />;
199	      }
200	
201	      return (
202	        <SingleMessageType
203	          roomId={roomId}
204	          event={item.data}
205	          isPreviousSameSender={item.isPreviousSameSender}
206	          onMemberPress={openMemberDetails}
207	        />
208	      );
209	    },
210	    [roomId, openMemberDetails],
211	  );
212	
213	  return (
214	    <>
215	      <KeyboardAvoidingView style={styles.flex} behavior="padding">
216	        {!!violatingUsers.length && (
217	          <RoomIdentityBanner
218	            users={violatingUsers}
219	            isLoading={isPinViolatingUsersLoading}
220	            onDismiss={pinViolatingUsers}
221	          />
222	        )}
223	        <FlashList
224	          ref={flashListRef}
225	          data={eventsWithDividers}
226	          keyExtractor={(item) => {
227	            if (item.type === "divider") return item.id;
228	            if (item.type === "group") return item.id;
229	
230	            return getItemUniqueKey(item.data) ?? "";
231	          }}
232	          maintainVisibleContentPosition={{
233	            startRenderingFromBottom: true,
234	          }}
235	          contentContainerStyle={styles.listContent}
236	          refreshing={refreshing}
237	          onContentSizeChange={handleContentSizeChange}
238	          onRefresh={handleLoadMore}
239	          onScroll={handleOnScroll}
240	          renderItem={renderItem}
241	        />
242	
243	        <RoomInput roomId={roomId} />
244	      </KeyboardAvoidingView>
245	
246	      <MessageContentBottomSheet roomId={roomId} />
247	
248	      <MemberDetailsBottomSheet
249	        isBottomSheetOpen={isBottomSheetOpen}
250	        selectedMember={selectedMember}
251	        roomId={roomId}
252	        onClose={closeMemberDetails}
253	      />
254	
255	      {showScrollDown && (
256	        <Block
257	          absolute
258	          offsets={{ right: 0, bottom: 100 }}
259	          align="center"
260	          justify="center"
261	          width="100%"
262	        >
263	          <Button.Outline size="medium" onPress={handleScrollDown}>
264	            <Text>New messages</Text>
265	            <Image source={require("assets/icons/arrow-down.png")} />
266	          </Button.Outline>
267	        </Block>
268	      )}
269	
270	      <SeenByBottomSheet
271	        isOpen={!!seenByUserIds}
272	        userIds={seenByUserIds ?? []}
273	        onClose={() => setSeenByUserIds(null)}
274	      />
275	    </>
276	  );
277	};
278	
279	const styles = StyleSheet.create({
280	  flex: {
281	    flex: 1,
282	  },
283	  listContent: {
284	    paddingHorizontal: 20,
285	    paddingTop: 12,
286	    paddingBottom: 20,
287	  },
288	});
