184	    let timelineListenerHandle: TaskHandleInterface | null = null;
185	    let isDisposed = false;
186	
187	    const initRoomTimeline = async () => {
188	      try {
189	        const timeline = await room.timelineWithConfiguration({
190	          focus: new TimelineFocus.Live({ hideThreadedEvents: false }),
191	          filter: new TimelineFilter.All(),
192	          internalIdPrefix: undefined,
193	          dateDividerMode: DateDividerMode.Daily,
194	          trackReadReceipts: TimelineReadReceiptTracking.AllEvents,
195	          reportUtds: false,
196	        });
197	
198	        // Store timeline in ref for reuse in pagination
199	        timelineRef.current = timeline;
200	
201	        // Set up listener BEFORE paginateBackwards so the SDK's initial
202	        // cached diffs (from SQLite) are received immediately — no network needed.
203	        // Set up timeline listener for real-time updates
204	        timelineListenerHandle = await timeline.addListener({
205	          onUpdate: (diffs) => {
206	            const beforeCount = timelineItemsRef.current.length;
207	            diffs.forEach((diff) => {
208	              const change = diff.tag;
209	              const timelineItems = timelineItemsRef.current;
210	              switch (change) {
211	                case TimelineDiff_Tags.Append: {
212	                  if (diff.inner.values.length > 0) {
213	                    timelineItems.push(...diff.inner.values.map(toEventItem));
214	                  }
215	                  break;
216	                }
217	                case TimelineDiff_Tags.Insert: {
218	                  const { index, value } = diff.inner;
219	                  timelineItems.splice(index, 0, toEventItem(value));
220	                  break;
221	                }
222	                case TimelineDiff_Tags.Set: {
223	                  const { index, value } = diff.inner;
224	                  const ev = toEventItem(value);
225	                  timelineItems[index] = ev;
226	
227	                  // transactionId -> eventId transition can arrive in an order where
228	                  // a stale local echo still exists elsewhere in the list.
229	                  if (
230	                    ev?.isOwn &&
231	                    !ev.localSendState &&
232	                    pendingTransactionIdsQueue.current.length > 0
233	                  ) {
234	                    const txId = pendingTransactionIdsQueue.current.shift();
235	                    if (txId) {
236	                      const txIndex = timelineItems.findIndex((item) => {
237	                        if (!item) return false;
238	                        return getItemUniqueKey(item) === txId;
239	                      });
240	                      if (txIndex !== -1) {
241	                        timelineItems[txIndex] = ev;
242	                      }
243	                    }
244	                  }
245	                  break;
246	                }
247	                case TimelineDiff_Tags.Remove: {
248	                  const { index: removeIndex } = diff.inner;
249	                  if (removeIndex >= 0 && removeIndex < timelineItems.length) {
250	                    timelineItems.splice(removeIndex, 1);
251	                  }
252	                  break;
253	                }
254	                case TimelineDiff_Tags.PushFront: {
255	                  const { value } = diff.inner;
256	                  timelineItems.unshift(toEventItem(value));
257	                  break;
258	                }
259	                case TimelineDiff_Tags.PushBack: {
260	                  const { value } = diff.inner;
261	                  const ev = toEventItem(value);
262	                  timelineItems.push(ev);
263	                  if (ev) {
264	                    const txId = getTransactionId(ev);
265	                    if (txId) {
266	                      pendingTransactionIdsQueue.current.push(txId);
267	                    }
268	                  }
269	                  break;
270	                }
271	                case TimelineDiff_Tags.PopFront: {
272	                  timelineItems.shift();
273	                  break;
274	                }
275	                case TimelineDiff_Tags.PopBack: {
276	                  timelineItems.pop();
277	                  break;
278	                }
279	                case TimelineDiff_Tags.Reset: {
280	                  const resetItems = diff.inner.values;
281	                  pendingTransactionIdsQueue.current = [];
282	                  timelineItemsRef.current = resetItems.map(toEventItem);
283	
284	                  const eventItems = timelineItemsRef.current.filter(
285	                    (i): i is EventTimelineItem => !!i,
286	                  );
287	                  pendingTransactionIdsQueue.current = eventItems
288	                    .map(getTransactionId)
289	                    .filter((id): id is string => !!id);
290	                  break;
291	                }
292	                case TimelineDiff_Tags.Truncate: {
293	                  const { length: cut } = diff.inner;
294	                  timelineItems.length = cut;
295	                  break;
296	                }
297	                case TimelineDiff_Tags.Clear: {
298	                  timelineItemsRef.current = [];
299	                  pendingTransactionIdsQueue.current = [];
300	                  eventIdsRef.current = new Set();
301	                  setEvents([]);
302	                  break;
303	                }
304	                default:
305	                  console.log("Unknown timeline change type:", change);
306	              }
307	            });
308	
309	            if (diffs.some((diff) => diff.tag !== TimelineDiff_Tags.Clear)) {
310	              if (rebuildTimerRef.current) clearTimeout(rebuildTimerRef.current);
311	              rebuildTimerRef.current = setTimeout(
312	                rebuildEventsFromTimelineItems,
313	                0,
314	              );
315	            }
316	
317	            if (ENABLE_TIMELINE_DEBUG) {
318	              const afterCount = timelineItemsRef.current.length;
319	              const tags = diffs.map((d) => d.tag).join(", ");
320	              console.log(
321	                `[TimelineDebug][${roomId}] diffs=[${tags}] items ${beforeCount}->${afterCount}`,
322	              );
323	            }
324	
325	          },
326	        });
327	
328	        // Paginate after the listener is set up so events flow through it.
329	        // Don't await — cached messages are already visible; network results
330	        // will arrive as further diffs without blocking the UI.
331	        isPaginatingRef.current = true;
332	        timeline.paginateBackwards(TIMELINE_PAGE_SIZE).catch((error) => {
333	          if (isDisposed) return;
334	          console.warn("Failed to load initial messages:", error);
335	        }).finally(() => {
336	          isPaginatingRef.current = false;
337	        });
338	      } catch (error) {
339	        console.error("Failed to initialize room timeline:", error);
340	        offlineToastHelper("Failed to load the messages. Please try again.");
341	        NavigationContainerRef.goBack();
342	        return null;
343	      }
344	    };
345	
346	    initRoomTimeline();
347	
348	    return () => {
349	      isDisposed = true;
350	      timelineListenerHandle?.cancel?.();
351	      if (rebuildTimerRef.current) clearTimeout(rebuildTimerRef.current);
352	      timelineRef.current = null;
353	      timelineItemsRef.current = [];
354	      isPaginatingRef.current = false;
355	      setRefreshing(false);
356	    };
357	  }, [rebuildEventsFromTimelineItems, room, roomId]);
358	
359	  useEffect(() => {
360	    markAsRead().catch(console.error);
361	    room?.isDirect().then(setIsDirect).catch(console.error);
362	  }, [room, markAsRead]);
363	
364	  return {
365	    events,
366	    refreshing,
367	    timelineRef,
368	    isPaginatingRef,
369	    isDirect,
370	    loadMoreMessages,
371	    markAsRead,
372	  };
373	};
